/* Compact messaging on pages other than the full Messages workspace. */
const MessageWidget={active:null,minimized:false,listOpen:false,notice:null,announcement:'',signature:'',messageSignature:'',errors:new Map(),reading:new Set()};
function resetMessageWidget(){document.querySelector('#message-widget')?.remove();Object.assign(MessageWidget,{active:null,minimized:false,listOpen:false,notice:null,announcement:'',signature:'',messageSignature:'',errors:new Map(),reading:new Set()})}
function messageWidgetVisible(){return Messaging.ready&&Messaging.owner===messagingActor()&&Boolean(Messaging.owner)&&location.hash!=='#messages'}
function notifyMessageWidget(previous,rows){if(!messageWidgetVisible())return;const counts=new Map(previous.map(row=>[row.id,Number(row.unread||0)]));const incoming=rows.filter(row=>!row.archived&&Number(row.unread||0)>(counts.get(row.id)||0));if(!incoming.length)return;const row=incoming[0];MessageWidget.announcement='New message from '+row.contact.name;if(!MessageWidget.active&&!MessageWidget.listOpen){MessageWidget.active=row.other_id;MessageWidget.minimized=false}else if(MessageWidget.active!==row.other_id)MessageWidget.notice=row.other_id}
async function refreshMessageWidgetMessages(){if(!messageWidgetVisible()||!MessageWidget.active||MessageWidget.minimized||MessageWidget.listOpen)return;const row=conversationFor(MessageWidget.active);if(row)await loadChatMessages(row.id)}
function miniChatIcon(name){const paths={close:'M6 6l12 12M18 6 6 18',minimize:'M5 12h14',up:'m6 15 6-6 6 6',down:'m6 9 6 6 6-6',open:'M14 4h6v6M20 4 10 14M10 4H5a1 1 0 0 0-1 1v14a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5'};return `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]}"/></svg>`}
function widgetControl(label,action,content){return `<button type="button" class="mini-chat-control" aria-label="${label}" title="${label}" onclick="${action}">${content}</button>`}
function renderMessageWidget(){let root=document.querySelector('#message-widget');if(!messageWidgetVisible()){if(root)root.hidden=true;return}if(!root){root=document.createElement('div');root.id='message-widget';root.className='message-widget';document.body.append(root);MessageWidget.signature=''}root.hidden=false;
 if(MessageWidget.active&&!conversationFor(MessageWidget.active)){MessageWidget.active=null;MessageWidget.signature=''}
 const p=person(MessageWidget.active),row=conversationFor(MessageWidget.active),key=[Messaging.owner,p?.id||'',MessageWidget.minimized,MessageWidget.listOpen].join(':');
 if(MessageWidget.signature!==key){MessageWidget.signature=key;MessageWidget.messageSignature='';root.innerHTML=`<div id="mini-chat-notice" class="mini-chat-notice" hidden></div>${MessageWidget.listOpen?`<section class="mini-chat mini-chat-list" aria-label="Recent conversations"><div class="mini-chat-heading"><b>Messaging</b><a href="#messages" class="mini-chat-full">Open Messages →</a>${widgetControl('Close conversation list','toggleMessageWidgetList()',miniChatIcon('close'))}</div><div id="mini-chat-conversations" class="mini-chat-conversations"></div></section>`:p&&row?`<section class="mini-chat ${MessageWidget.minimized?'mini-chat-minimized':''}" aria-label="Chat with ${esc(p.name)}"><div class="mini-chat-heading"><button type="button" class="mini-chat-person" aria-label="${MessageWidget.minimized?'Expand':'Minimize'} chat with ${esc(p.name)}" onclick="toggleMiniChat()">${portrait(p)}<span><b>${esc(p.name)}</b><small>${esc(p.company||p.role)}</small></span></button><span id="mini-chat-unread" class="mini-chat-count" hidden></span>${widgetControl('Open full Messages','openWidgetInMessages()',miniChatIcon('open'))}${widgetControl(MessageWidget.minimized?'Expand chat':'Minimize chat','toggleMiniChat()',miniChatIcon(MessageWidget.minimized?'up':'minimize'))}${widgetControl('Close chat','closeMiniChat()',miniChatIcon('close'))}</div>${!MessageWidget.minimized?`<div id="mini-chat-scroll" class="mini-chat-scroll" aria-label="Conversation messages"></div><form id="mini-chat-form" class="mini-chat-form"><label class="messages-page-title" for="mini-chat-input">Reply to ${esc(p.name)}</label><textarea id="mini-chat-input" rows="2" maxlength="4000" placeholder="Write a reply…"></textarea><div id="mini-chat-attachments" class="mini-chat-attachments"></div><div class="mini-chat-composer-actions"><small>Enter to send · Shift + Enter for a new line</small><button type="submit" id="mini-chat-send" class="primary">Send ${icon('send',14)}</button></div><p id="mini-chat-feedback" class="mini-chat-feedback" role="status"></p></form>`:''}</section>`:''}<button type="button" id="message-widget-launcher" class="message-widget-launcher" aria-expanded="${MessageWidget.listOpen}" onclick="toggleMessageWidgetList()">${icon('message',18)}<span>Messaging</span><b id="message-widget-count" class="mini-chat-count" hidden></b><span aria-hidden="true">${miniChatIcon(MessageWidget.listOpen?'down':'up')}</span></button><span id="message-widget-announcement" class="messages-page-title" role="status" aria-live="polite" aria-atomic="true"></span>`;bindMessageWidget(root)}
 const total=unreadCount(),count=root.querySelector('#message-widget-count');count.hidden=!total;count.textContent=total>99?'99+':String(total);root.querySelector('#message-widget-launcher').setAttribute('aria-label','Messaging'+(total?', '+total+' unread messages':''));
 const notice=root.querySelector('#mini-chat-notice'),contact=Number(conversationFor(MessageWidget.notice)?.unread)?person(MessageWidget.notice):null;if(!contact)MessageWidget.notice=null;notice.hidden=!contact;if(contact)notice.innerHTML=`<button type="button" onclick="openMiniChat('${contact.id}')"><b>New message</b><span>${esc(contact.name)} · View conversation</span></button>${widgetControl('Dismiss message notification','dismissMiniChatNotice()',miniChatIcon('close'))}`;
 const live=root.querySelector('#message-widget-announcement');if(live.textContent!==MessageWidget.announcement)live.textContent=MessageWidget.announcement;
 if(MessageWidget.listOpen){root.querySelector('#mini-chat-conversations').innerHTML=Messaging.inbox.filter(row=>!row.archived).map(row=>{const p=person(row.other_id),last=row.last_message;return `<button type="button" class="mini-chat-thread ${Number(row.unread)?'is-unread':''}" onclick="openMiniChat('${p.id}')">${portrait(p)}<span><b>${esc(p.name)}</b><small>${esc(last?.deleted_at?'Message removed':last?.body||last?.filename||last?.listing?.title||'Start a conversation')}</small></span>${Number(row.unread)?`<strong class="mini-chat-count">${Number(row.unread)}</strong>`:''}</button>`}).join('')||'<p class="mini-chat-empty">No conversations yet. Open Messages to start one.</p>';return}
 if(!p||!row)return;const unread=root.querySelector('#mini-chat-unread');unread.hidden=!Number(row.unread);unread.textContent=String(row.unread||0);if(MessageWidget.minimized)return;
 const scroll=root.querySelector('#mini-chat-scroll'),messages=Messaging.messages.get(row.id),signature=JSON.stringify(messages||null);if(signature!==MessageWidget.messageSignature){const nearBottom=scroll.scrollHeight-scroll.scrollTop-scroll.clientHeight<70,first=!MessageWidget.messageSignature;MessageWidget.messageSignature=signature;scroll.innerHTML=chatMessages(p,true);if(nearBottom||first)scroll.scrollTop=scroll.scrollHeight}
 const draft=attachmentDraft(p.id),input=root.querySelector('#mini-chat-input');if(input.value!==draft.text)input.value=draft.text;input.disabled=draft.sending;const send=root.querySelector('#mini-chat-send');send.disabled=draft.sending||(!draft.text.trim()&&!draft.files.length);send.innerHTML=draft.sending?'Sending…':'Send '+icon('send',14);root.querySelector('#mini-chat-attachments').innerHTML=draft.files.length?'<small>Attached: '+draft.files.map(file=>esc(file.name)).join(', ')+' · <button type="button" onclick="openWidgetInMessages()">Manage in Messages</button></small>':'';root.querySelector('#mini-chat-feedback').textContent=MessageWidget.errors.get(p.id)||Messaging.error||'';readFocusedMiniChat();
}
function bindMessageWidget(root){const input=root.querySelector('#mini-chat-input'),form=root.querySelector('#mini-chat-form');if(input){input.oninput=()=>{attachmentDraft(MessageWidget.active).text=input.value;renderMessageWidget()};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMiniChat()}};form.onsubmit=e=>{e.preventDefault();sendMiniChat()}}
 root.onfocusin=readFocusedMiniChat;root.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();if(MessageWidget.listOpen)toggleMessageWidgetList();else closeMiniChat()}};
}
function readFocusedMiniChat(){const root=document.querySelector('#message-widget'),row=conversationFor(MessageWidget.active);if(document.activeElement?.closest('.mini-chat-heading'))return;if(!root||!row||!Number(row.unread)||MessageWidget.reading.has(row.id)||MessageWidget.minimized||MessageWidget.listOpen||!document.hasFocus()||document.hidden||!root.querySelector('.mini-chat')?.contains(document.activeElement))return;const cached=Messaging.messages.get(row.id);if(!cached||row.last_message?.created_at&&(!cached.length||cached.at(-1).created_at<row.last_message.created_at))return;MessageWidget.reading.add(row.id);markConversationRead(row.id).finally(()=>MessageWidget.reading.delete(row.id))}
async function openMiniChat(id){if(!messageWidgetVisible()||!conversationFor(id))return;const service=Messaging.service;MessageWidget.active=id;MessageWidget.minimized=false;MessageWidget.listOpen=false;if(MessageWidget.notice===id)MessageWidget.notice=null;renderMessageWidget();try{await loadChatMessages(conversationFor(id).id);service.current();if(MessageWidget.active!==id)return;renderMessageWidget();document.querySelector('#mini-chat-input')?.focus();if(document.hasFocus()&&!document.hidden)await markConversationRead(conversationFor(id).id)}catch(error){if(service===Messaging.service){MessageWidget.errors.set(id,messagingError(error));renderMessageWidget()}}}
function closeMiniChat(){MessageWidget.active=null;MessageWidget.minimized=false;MessageWidget.listOpen=false;renderMessageWidget();document.querySelector('#message-widget-launcher')?.focus()}
function toggleMiniChat(){MessageWidget.minimized=!MessageWidget.minimized;renderMessageWidget();if(!MessageWidget.minimized){const row=conversationFor(MessageWidget.active);if(row)loadChatMessages(row.id).then(()=>{renderMessageWidget();if(MessageWidget.active===row.other_id&&!MessageWidget.minimized&&document.hasFocus()&&!document.hidden)markConversationRead(row.id)}).catch(error=>{MessageWidget.errors.set(MessageWidget.active,messagingError(error));renderMessageWidget()})}document.querySelector('.mini-chat-person')?.focus()}
function toggleMessageWidgetList(){MessageWidget.listOpen=!MessageWidget.listOpen;renderMessageWidget();document.querySelector('#message-widget-launcher')?.focus()}
function dismissMiniChatNotice(){MessageWidget.notice=null;renderMessageWidget()}
function openWidgetInMessages(){const id=MessageWidget.active;if(id)openConversation(id);else location.hash='messages'}
async function sendMiniChat(){const id=MessageWidget.active,row=conversationFor(id),service=Messaging.service;if(!row||!messageWidgetVisible())return;const draft=attachmentDraft(id);if(draft.sending||(!draft.text.trim()&&!draft.files.length))return;draft.sending=true;MessageWidget.errors.delete(id);renderMessageWidget();try{await persistMessageDraft(row,draft);service.current();if(MessageWidget.active===id){renderMessageWidget();const scroll=document.querySelector('#mini-chat-scroll');if(scroll)scroll.scrollTop=scroll.scrollHeight}}catch(error){if(service===Messaging.service)MessageWidget.errors.set(id,messagingError(error))}finally{draft.sending=false;if(service===Messaging.service){renderMessageWidget();if(MessageWidget.active===id&&!MessageWidget.minimized&&!MessageWidget.listOpen&&(document.activeElement===document.body||document.querySelector('#message-widget')?.contains(document.activeElement)))document.querySelector('#mini-chat-input')?.focus()}}}

window.addEventListener('hashchange',()=>{renderMessageWidget();if(messageWidgetVisible())scheduleMessagingRefresh()});
